#!/usr/bin/env node
// Generates src/entities/data.ts from the vendored copy of the WHATWG's own
// machine-readable named-character-reference table.
//
// Implements the named character reference table per
// https://html.spec.whatwg.org/multipage/named-characters.html
// Source data: https://html.spec.whatwg.org/entities.json — vendored beside this
// script as `entities.json` so regeneration needs no network, and so a diff of
// the generated file is explained by a diff of its input.
//
// Run: node packages/web/domparser/scripts/generate-entities.mjs

import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const here = fileURLToPath(new URL('.', import.meta.url));
const source = JSON.parse(readFileSync(here + 'entities.json', 'utf8'));
const target = here + '../src/entities/data.ts';

/** ASCII-only output: every character is written as a \uXXXX escape, one per
 *  UTF-16 code unit, so the file carries no encoding assumption and no quote to
 *  escape. */
function escapeValue(value) {
    let out = '';
    for (let i = 0; i < value.length; i++) {
        const unit = value.charCodeAt(i);
        // A raw NUL in a bundled source file terminates the script under GJS's
        // minifier. Nothing in the spec table has one; assert rather than assume.
        if (unit === 0) throw new Error('entity value contains U+0000 — refusing to generate');
        out += '\\u' + unit.toString(16).toUpperCase().padStart(4, '0');
    }
    return out;
}

const IDENTIFIER = /^[A-Za-z_$][A-Za-z0-9_$]*$/;

const entries = Object.keys(source)
    .map((key) => {
        // The spec keys carry the leading `&`; ours are keyed by what follows it,
        // trailing `;` included, so longest-match resolves `&amp;` over `&amp`.
        if (!key.startsWith('&')) throw new Error('unexpected key without "&": ' + key);
        return [key.slice(1), source[key].characters];
    })
    .sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0));

if (entries.length < 2000) throw new Error('source table has only ' + entries.length + ' entries');

const body = entries
    .map(([key, value]) => {
        const name = IDENTIFIER.test(key) ? key : "'" + key + "'";
        return '    ' + name + ": '" + escapeValue(value) + "',";
    })
    .join('\n');

const header = `// GENERATED by scripts/generate-entities.mjs — do not edit.
//
// The HTML named character references, keyed by the text BETWEEN \`&\` and the
// end of the reference; the trailing \`;\` is part of the key on purpose. The
// spec's table carries both spellings for the legacy references (\`&amp;\` and
// \`&amp\`), and the decoder resolves by longest match against exactly these keys,
// so a key ending in \`;\` automatically wins over its semicolon-less prefix.
//
// Implements the named character reference table per
// https://html.spec.whatwg.org/multipage/named-characters.html
// Source data: https://html.spec.whatwg.org/entities.json (vendored at
// scripts/entities.json).
//
// The full table is here rather than a popular subset because a subset fails
// SILENTLY: \`&hellip;\` would stay raw, nothing throws, no test reddens, and the
// caller gets a wrong string (ADR 0026 § Decision 5).

export const NAMED_REFERENCES: Record<string, string> = {
`;

// The matcher's lookahead window. Emitted as a literal rather than derived at
// run time from `Object.keys(...)`: that call is a module-level side effect a
// bundler must assume matters, and it pins the whole table live for every
// consumer of this file — including `decodeXml`, which can never read it.
const maxKeyLength = entries.reduce((max, [key]) => (key.length > max ? key.length : max), 0);
const footer = `};

/** Length of the longest key above, so the matcher's window follows the data. */
export const MAX_NAMED_REFERENCE_LENGTH = ${maxKeyLength};
`;

writeFileSync(target, header + body + '\n' + footer);
console.log('wrote ' + entries.length + ' references to src/entities/data.ts');
